package cmdinternal

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"time"

	"github.com/devsy-org/devsy/cmd/flags"
	"github.com/devsy-org/devsy/pkg/config"
	"github.com/devsy-org/devsy/pkg/devcontainer"
	cliflags "github.com/devsy-org/devsy/pkg/flags"
	"github.com/devsy-org/devsy/pkg/flags/names"
	"github.com/devsy-org/devsy/pkg/log"
	"github.com/spf13/cobra"
)

type GetWorkspaceConfigCommand struct {
	*flags.GlobalFlags

	timeout  time.Duration
	maxDepth int
}
type GetWorkspaceConfigCommandResult struct {
	IsImage         bool     `json:"isImage"`
	IsGitRepository bool     `json:"isGitRepository"`
	IsLocal         bool     `json:"isLocal"`
	ConfigPaths     []string `json:"configPaths"`
}

// NewGetWorkspaceConfigCommand creates a new command.
func NewGetWorkspaceConfigCommand(flags *flags.GlobalFlags) *cobra.Command {
	cmd := &GetWorkspaceConfigCommand{
		GlobalFlags: flags,
	}
	shellCmd := &cobra.Command{
		Use:   "get-workspace-config",
		Short: "Retrieves a workspace config",
		RunE: func(cobraCmd *cobra.Command, args []string) error {
			devsyConfig, err := config.LoadConfig(cmd.Context, cmd.Provider)
			if err != nil {
				return err
			}

			if cmd.maxDepth < 0 {
				log.Debugf("--max-depth was %d, setting to 0", cmd.maxDepth)
				cmd.maxDepth = 0
			}

			return cmd.Run(cobraCmd.Context(), devsyConfig, args)
		},
	}

	cliflags.Add(
		shellCmd,
		cliflags.Duration(
			&cmd.timeout,
			names.Timeout,
			10*time.Second,
			"Timeout for the command, 10 seconds by default",
		),
		cliflags.Int(
			&cmd.maxDepth,
			names.MaxDepth,
			3,
			"Maximum depth to search for devcontainer files",
		),
	)

	return shellCmd
}

func (cmd *GetWorkspaceConfigCommand) Run(
	ctx context.Context,
	devsyConfig *config.Config,
	args []string,
) error {
	if len(args) != 1 {
		return fmt.Errorf("workspace source is missing")
	}
	rawSource := args[0]

	log.Debugf("Resolving devcontainer config for source: %s", rawSource)

	ctx, cancel := context.WithTimeout(context.Background(), cmd.timeout)
	defer cancel()

	done := make(chan *devcontainer.GetWorkspaceConfigResult, 1)
	errChan := make(chan error, 1)

	tmpDir, err := os.MkdirTemp("", config.BinaryName)
	if err != nil {
		return err
	}
	defer func() {
		_ = os.RemoveAll(tmpDir)
	}()
	go func() {
		result, err := devcontainer.FindDevcontainerFiles(
			ctx,
			rawSource,
			tmpDir,
			cmd.maxDepth,
			devsyConfig.ContextOptionBool(config.ContextOptionSSHStrictHostKeyChecking),
		)
		if err != nil {
			errChan <- err
			return
		}
		done <- result
	}()

	select {
	case err := <-errChan:
		return fmt.Errorf("unable to find devcontainer files: %w", err)
	case <-ctx.Done():
		return fmt.Errorf("timeout while searching for devcontainer files")
	case result := <-done:
		out, err := json.Marshal(result)
		if err != nil {
			return err
		}
		fmt.Println(string(out))
	}
	defer close(done)

	return nil
}
